def table(headers,rows):
 t=doc.add_table(rows=1,cols=len(headers));t.style='Table Grid'
 borders=OxmlElement('w:tblBorders')
 for edge in ['top','left','bottom','right','insideH','insideV']:
  b=OxmlElement('w:'+edge);b.set(qn('w:val'),'single');b.set(qn('w:sz'),'4');b.set(qn('w:color'),'CCCCCC');borders.append(b)
 t._tbl.tblPr.append(borders)
 for c,v in zip(t.rows[0].cells,headers):c.text=v
 for row in rows:
  for c,v in zip(t.add_row().cells,row):c.text=v
 for row in t.rows:
  trPr=row._tr.get_or_add_trPr(); no=OxmlElement('w:cantSplit');trPr.append(no)
  for c in row.cells:
   for para in c.paragraphs:
    para.paragraph_format.space_after=Pt(5)
    for r in para.runs:r.font.size=Pt(9)
 for c in t.rows[0].cells:
  shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'EEEEEE');c._tc.get_or_add_tcPr().append(shade)
  for r in c.paragraphs[0].runs:r.bold=True
 repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
 p('')

